story:
{
  "title": "笔尖的温暖",
  "description": "一个关于通过写作找到内心平静的治愈故事，展现文字如何成为心灵的慰藉",
  "scenes": [
    {
      "scene_number": 1,
      "description": "一位年轻人坐在书桌前，面露疲惫，周围是散落的纸张和书籍",
      "prompt": "A young person sitting at a wooden desk, looking tired and overwhelmed, surrounded by scattered papers and books, soft natural lighting, warm atmosphere",
      "duration": 3
    },
    {
      "scene_number": 2,
      "description": "他拿起笔，在笔记本上开始书写，表情逐渐平静",
      "prompt": "The young person picks up a pen and starts writing in a notebook, his expression gradually calming down, focused and peaceful, close-up of hands writing",
      "duration": 4
    },
    {
      "scene_number": 3,
      "description": "他微笑着看着自己的文字，阳光洒在笔记本上，充满希望",
      "prompt": "He smiles as he looks at his writing, sunlight streaming through the window onto the notebook, creating a hopeful and warm atmosphere, gentle smile",
      "duration": 3
    }
  ]
}
